/**
 * Canonical shared SITREP combatant semantics.
 * Presentation-free and hook-free. Generic Foundry spatial behavior does not belong here.
 */

export const SITREP_FACTIONS = Object.freeze({
  FRIENDLY: "friendly",
  HOSTILE: "hostile",
  NEUTRAL: "neutral"
});

export function tokenDisposition(tokenDocument) {
  return Number(tokenDocument?.disposition ?? 0);
}

export function factionOf(tokenDocument, dispositionConstants = globalThis.CONST?.TOKEN_DISPOSITIONS) {
  const disposition = tokenDisposition(tokenDocument);
  const friendly = Number(dispositionConstants?.FRIENDLY ?? 1);
  const hostile = Number(dispositionConstants?.HOSTILE ?? -1);
  if (disposition === friendly) return SITREP_FACTIONS.FRIENDLY;
  if (disposition === hostile) return SITREP_FACTIONS.HOSTILE;
  return SITREP_FACTIONS.NEUTRAL;
}

export function combatantIsDefeated(combatant, defeatedStatusId = globalThis.CONFIG?.specialStatusEffects?.DEFEATED) {
  if (typeof combatant?.isDefeated === "boolean") return combatant.isDefeated;
  if (combatant?.defeated === true) return true;
  return Boolean(defeatedStatusId && combatant?.actor?.statuses?.has?.(defeatedStatusId));
}

export function combatantById(combat, combatantId) {
  return combat?.combatants?.get?.(combatantId) ?? null;
}

export function collectStandingSitrepCombatants(combat, { controlWeightForActor = () => 1 } = {}) {
  const standing = [];
  for (const combatant of combat?.combatants ?? []) {
    if (combatantIsDefeated(combatant)) continue;
    const token = combatant?.token ?? null;
    if (!token) continue;
    const faction = factionOf(token);
    if (faction === SITREP_FACTIONS.NEUTRAL) continue;
    const actor = token.actor ?? combatant.actor ?? null;
    const controlWeight = Number(controlWeightForActor(actor));
    standing.push(Object.freeze({ combatant, token, actor, faction, controlWeight: Number.isFinite(controlWeight) ? controlWeight : 1 }));
  }
  return standing;
}

/** Canonical shared SITREP control-count semantics. */

export const SITREP_CONTROLLERS = Object.freeze({
  FRIENDLY: "friendly",
  HOSTILE: "hostile",
  CONTESTED: "contested",
  NONE: "none"
});

export function controllerFromCounts(friendly, hostile) {
  const friendlyCount = Number(friendly ?? 0);
  const hostileCount = Number(hostile ?? 0);
  if (friendlyCount > hostileCount) return SITREP_CONTROLLERS.FRIENDLY;
  if (hostileCount > friendlyCount) return SITREP_CONTROLLERS.HOSTILE;
  return SITREP_CONTROLLERS.CONTESTED;
}

/** Canonical shared SITREP round/final-round calculations. */

export function currentSitrepRound(combat, sitrep) {
  return Math.max(Number(combat?.round ?? sitrep?.startRound ?? 1), 1);
}

export function sitrepRoundsRemaining(combat, sitrep) {
  const currentRound = currentSitrepRound(combat, sitrep);
  const finalRound = Math.max(Number(sitrep?.finalRound ?? currentRound), currentRound);
  return Math.max(finalRound - currentRound + 1, 0);
}

export function isSitrepFinalRound(combat, sitrep) {
  return currentSitrepRound(combat, sitrep) >= Number(sitrep?.finalRound ?? Infinity);
}

export function isSitrepRoundPastLimit(combat, sitrep) {
  return currentSitrepRound(combat, sitrep) > Number(sitrep?.finalRound ?? Infinity);
}

/**
 * SITREP-specific spatial delegation boundary.
 * Owns no geometry, token-footprint math, Region implementation, or canvas lookup.
 */

const REQUIRED_SITREP_SPATIAL_OPERATIONS = Object.freeze(["resolveRegion", "tokenInsideRegion", "tokensAreAdjacent"]);

export function assertSitrepSpatialOperations(operations) {
  if (!operations || typeof operations !== "object" || Array.isArray(operations)) {
    throw new TypeError("SITREP spatial operations must be supplied as an object.");
  }
  for (const operationName of REQUIRED_SITREP_SPATIAL_OPERATIONS) {
    if (typeof operations[operationName] !== "function") {
      throw new Error(`SITREP spatial operations require ${operationName}().`);
    }
  }
  return operations;
}

export function resolveConfiguredSitrepRegion(operations, combat, regionId) {
  assertSitrepSpatialOperations(operations);
  if (!regionId) return null;
  return operations.resolveRegion({ combat, regionId }) ?? null;
}

export function resolveConfiguredSitrepRegions(operations, combat, regionIds) {
  assertSitrepSpatialOperations(operations);
  const ids = Array.isArray(regionIds) ? regionIds : [];
  return ids.map(regionId => resolveConfiguredSitrepRegion(operations, combat, regionId)).filter(Boolean);
}

export function tokenInsideConfiguredSitrepRegion(operations, tokenDocument, region) {
  assertSitrepSpatialOperations(operations);
  if (!tokenDocument || !region) return false;
  return Boolean(operations.tokenInsideRegion(tokenDocument, region));
}

export function sitrepTokensAreAdjacent(operations, firstToken, secondToken) {
  assertSitrepSpatialOperations(operations);
  if (!firstToken || !secondToken) return false;
  return Boolean(operations.tokensAreAdjacent(firstToken, secondToken));
}

/** Canonical Gauntlet control-weight semantics. */

export const GAUNTLET_NPC_TEMPLATE_WEIGHTS = Object.freeze({ npct_grunt: 0.25, npct_elite: 2, npct_ultra: 4 });

export function gauntletControlWeight(actor) {
  if (!actor || actor.type !== "npc") return 1;
  const templates = [...(actor.items ?? [])].filter(item => item?.type === "npc_template");
  const templateLids = new Set(templates.map(item => String(item?.system?.lid ?? "").trim().toLowerCase()));
  if (templateLids.has("npct_ultra")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_ultra;
  if (templateLids.has("npct_elite")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_elite;
  if (templateLids.has("npct_grunt")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_grunt;
  const templateNames = new Set(templates.map(item => String(item?.name ?? "").trim().toLowerCase()));
  if (templateNames.has("ultra")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_ultra;
  if (templateNames.has("elite")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_elite;
  if (templateNames.has("grunt")) return GAUNTLET_NPC_TEMPLATE_WEIGHTS.npct_grunt;
  return 1;
}
